from ode import *
def row(k,*fs,**kw):A.row('review',k,*fs,**kw)
row(1,c('a · Homogeneous equation','ay″+by′+cy=0, a≠0, with constant a,b,c','ay″+by′+cy=x','ay′+by+c=0'),c('b · Auxiliary equation','ar²+br+c=0','ar+b+c=0','ar²+br−c=0'),c('c · Distinct real roots r₁,r₂','y=C₁e^(r₁x)+C₂e^(r₂x)','y=(C₁+C₂x)e^(r₁x)','y=C₁cos(r₁x)+C₂sin(r₂x)'),c('c · Repeated real root r','y=(C₁+C₂x)e^(rx)','y=(C₁+C₂)e^(rx)','y=C₁e^(rx)+C₂e^(−rx)'),c('c · Roots α±iβ, β≠0','y=e^(αx)[C₁cos(βx)+C₂sin(βx)]','y=e^(βx)[C₁cos(αx)+C₂sin(αx)]','y=e^(αx)(C₁+C₂x)'),suffix='-concept-check-1',why='Substitution of e^(rx) yields the characteristic polynomial; each case supplies two independent homogeneous solutions.')
row(2,c('a · Initial-value problem','An ODE with y(a) and y′(a) specified at the same point','An ODE with y(a),y(b) specified at two different points','An ODE without any conditions'),c('b · Boundary-value problem','An ODE with endpoint conditions at different points, such as y(a),y(b)','An ODE with only y′(a) specified','An equation whose coefficients must vanish at endpoints'),suffix='-concept-check-1')
row(3,c('a · Nonhomogeneous equation','ay″+by′+cy=G(x), a≠0, constant coefficients','ay″+by′+cy=0 only','y″+y²=G(x)'),c('b · Complementary equation and solution','Solve ay″+by′+cy=0 for y_c, then y=y_c+y_p','Solve ay″+by′+cy=1, then multiply by G','Every solution is just one particular solution'),c('c · Undetermined coefficients','Choose a trial matching forcing; multiply resonant terms by a sufficient power of x, substitute and match coefficients','Use the forcing itself as y without testing','Always try a constant regardless of forcing'),c('d · Variation of parameters','For basis y₁,y₂ and W=y₁y₂′−y₁′y₂, integrate u₁′=−y₂G/(aW), u₂′=y₁G/(aW); y_p=u₁y₁+u₂y₂','Take u₁′=y₁G and u₂′=y₂G in every equation','Set both variable coefficients equal to G'),suffix='-concept-check-1',limited=True)
row(4,c('Spring model','mx″+cx′+kx=F(t), displacement measured from equilibrium','mx″−kx=0 for every spring','mx′+kx=F(t)'),c('Series RLC circuit','LQ″+RQ′+Q/C=E(t), I=Q′','LQ′+RQ+CQ=E(t)','LQ″−RQ′+CQ=0'),suffix='-concept-check-1',limited=True,why='Newton’s law and Kirchhoff’s voltage law lead to the same second-order linear structure, with mass/inductance, damping/resistance and stiffness/inverse capacitance corresponding.')
row(5,c('Power-series method','Substitute y=Σcₙx^n, differentiate, align powers, equate coefficients and use initial data to determine the starting coefficients','Set every coefficient equal to y(0)','Differentiate the equation until it becomes a polynomial'),c('Validity','The resulting series must converge on the interval where it is used','Any formal divergent series gives numerical answers','Convergence never matters'),suffix='-concept-check-1',limited=True)
for k,truth,reason in [(1,True,'The homogeneous linear operator applied to a sum is the sum of its zero outputs.'),(2,False,'The operator applied to C₁y₁+C₂y₂ gives (C₁+C₂)x, which equals x only under an additional restriction such as C₁+C₂=1.'),(3,True,'cosh x and sinh x are independent linear combinations of e^x and e^(−x).'),(4,False,'e^x is a homogeneous solution, so the proposed trial gives zero. Resonance requires a trial Ax e^x, with A=1/2.')]:row(k,c('Truth value','True' if truth else 'False','False' if truth else 'True'),suffix='-true-false-quiz-2',why=reason,limited=True)
for k,abc,rhs in [(1,(4,0,-1),0),(2,(1,-2,10),0),(3,(1,0,3),0),(4,(1,8,16),0),(5,(1,-4,5),s.exp(2*x)),(6,(1,1,-2),x*x),(7,(1,-2,1),x*s.cos(x)),(8,(1,0,4),s.sin(2*x)),(9,(1,-1,-6),1+s.exp(-2*x))]:row(k,answer(solve(abc,rhs),abc),why='Add a particular solution to the characteristic-root complementary solution. The proposed expression is verified by differentiating and substituting into the original equation.')
sol=C1*s.cos(x)+C2*s.sin(x)-x*s.cos(x)+s.sin(x)*s.log(s.sin(x));assert s.trigsimp(op(sol,(1,0,1))-s.csc(x))==0
row(10,answer(sol,(1,0,1)),c('Interval','0<x<π/2','All real x','x=0 only'),why='Variation of parameters with cos x,sin x gives u₁=−x and u₂=ln(sin x); the source interval makes sin x positive.')
cases.append(dict(coefficients=['1','0','1'],forcing='csc(x)',solution=str(sol),ics={}))
for k,abc,rhs,data in [(11,(1,6,0),0,iv(3,12,1)),(12,(1,-6,25),0,iv(2,1)),(13,(1,-5,4),0,iv(0,1)),(14,(9,0,1),3*x+s.exp(-x),iv(1,2))]:row(k,answer(solve(abc,rhs,data),abc),why='Apply both specified initial values after finding the general solution; verify the differential equation and both conditions.')
row(15,c('Boundary-value result','No solution','A unique solution','Infinitely many solutions'),why='y(0)=1 fixes the cosine coefficient; every such solution has y(π)=−e^(−2π), not −1.')
row(16,c('Complete solution family','y=e^(−2x)[cos(5x)+C sin(5x)], C arbitrary','No solution','y=e^(−2x)[sin(5x)+C cos(5x)]'),why='The sine term vanishes at both endpoints. The two boundary conditions agree and leave its coefficient free.')
row(17,c('Complete series','y=Σ(n=0…∞) (−1)^n x^(2n+1)/(3·5·…·(2n+1)), with empty product 1','y=Σ(n=0…∞) x^(2n+1)/(3·5·…·(2n+1))','y=sin x'),c('First terms','x−x³/3+x⁵/15−x⁷/105+…','x−x³/6+x⁵/120−…','1−x²/2+x⁴/8−…'),c('Convergence','All real x','|x|<1','|x|<2'),why='c₀=0,c₁=1; cₙ₊₂=−cₙ/(n+2), leaving only the displayed odd powers.')
row(18,c('Complete series definition','y=Σcₙx^n, c₀,c₁ arbitrary; cₙ₊₂=cₙ/(n+1), n≥0','cₙ₊₂=−cₙ/(n+1)','cₙ₊₂=cₙ/(n+2)'),c('First terms','c₀(1+x²+x⁴/3+x⁶/15+…)+c₁(x+x³/2+x⁵/8+x⁷/48+…)','c₀ cos x+c₁ sin x','c₀(1−x²+…)+c₁(x−x³/2+…)'),c('Convergence','All real x','|x|<1','|x|<2'),why='Match (n+2)(n+1)cₙ₊₂=(n+2)cₙ. This recurrence plus two arbitrary starting coefficients determines the entire solution series.')
row(19,answer(solve((2,40,400),12,iv(R(1,100),0)),(2,40,400),'Charge Q(t), coulombs',t),why='LQ″+RQ′+Q/C=12 with L=2,R=40,1/C=400, Q(0)=0.01 and Q′(0)=0.')
row(20,n('Spring constant',64,'N/m'),answer(solve((2,16,64),ics=iv(0,R(12,5))),(2,16,64),'Position x(t), meters',t),why='k=12.8/0.2=64 N/m. Solve 2x″+16x′+64x=0 with x(0)=0 and x′(0)=2.4.')
row(21,c('a · Interior gravitational force','F_r=−GMmr/R³','F_r=−GMm/r² for all interior r','F_r=−GMmr/R²'),c('b · Equation and released solution','y″=−(g/R)y and y(t)=R cos(√(g/R)t)','y″=−gy and y(t)=R cos(√g t)','y″=−g/y²'),c('c · Period','T=2π√(R/g)','T=2π√(g/R)','T=π√(R/g)'),c('d · Speed at the center','√(gR)=√(GM/R)','gR','2√(gR)'),limited=True,why='Uniform density gives M_r=M(r/R)³. Newton’s law produces a harmonic oscillator in the signed coordinate y; the physical distance is |y|. Release at rest from y=R, and use maximum speed ωR. Use consistent units for R=3960 mi and g.')
save('review')
